        assert "Object.assign(window" in js
        for key in ["AEE_CORE_ENGINES", "AEE_SUPPORT_SYSTEMS", "AEE_REGIME_DIMENSIONS",
                    "AEE_FEATURE_STATES", "AEE_SAMPLE_FEATURES", "AEE_WORKFLOW_STEPS",
